\set ON_ERROR_STOP on
begin;
insert into auth.users values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002'),('00000000-0000-0000-0000-000000000003');
insert into moderators values('00000000-0000-0000-0000-000000000003');
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.denied(command text,label text) returns void language plpgsql as $$ begin begin execute command;exception when others then raise notice 'PASS denied: %',label;return;end;raise exception 'FAIL allowed: %',label;end $$;
select pg_temp.assert_true((select count(*)=101 from observation_catalog_types),'101 canonical events seeded');
select pg_temp.denied($q$select catalog_policy(1,'travel','wildlife.sighting','animal_sighting','{}','{}')$q$,'cross-domain tampering');
select pg_temp.denied($q$select catalog_policy(1,'travel','travel.surface','black_ice','{}','{"animal":"bear"}')$q$,'irrelevant answers');
select pg_temp.denied($q$select catalog_policy(1,'wildlife','wildlife.sighting','animal_sighting','{}','{"animal":"moose","other_animal":"Hidden"}')$q$,'hidden dependent answers');
select pg_temp.denied($q$select catalog_policy(1,'travel','travel.surface','black_ice',array['nonexistent'],'{}')$q$,'unknown related event');
select pg_temp.denied($q$select catalog_policy(1,'travel','travel.surface','black_ice','{}','{"surface":"invented"}')$q$,'unknown choice');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
insert into observations(author_id,category,title,description,latitude,longitude,domain_id,topic_id,event_type_id,answers) values
(auth.uid(),'Travel','Black ice fixture','FICTIONAL TEST ONLY road condition.',61.2181,-149.9003,'travel','travel.surface','black_ice','{"visibility":"good"}'),
(auth.uid(),'Safety','Shooting fixture','FICTIONAL TEST ONLY sensitive incident.',61.2181,-149.9003,'safety','safety.public','shooting_witnessed','{}');
insert into observations(author_id,category,title,description,latitude,longitude,domain_id,topic_id,event_type_id,answers) values
(auth.uid(),'Outdoors','Bear encounter fixture','FICTIONAL TEST ONLY animal encounter.',61.2181,-149.9003,'wildlife','wildlife.encounter','animal_encounter','{"animal":"other","encounter_behavior":"attack","other_animal":"PRIVATE TEST DETAIL"}'),
(auth.uid(),'Safety','Missing person fixture','FICTIONAL TEST ONLY sensitive report.',61.2181,-149.9003,'safety','safety.restricted','missing_person','{}');
select set_config('test.road',id::text,true) from my_observations() where title='Black ice fixture';
select set_config('test.shooting',id::text,true) from my_observations() where title='Shooting fixture';
select set_config('test.bear',id::text,true) from my_observations() where title='Bear encounter fixture';
select set_config('test.missing',id::text,true) from my_observations() where title='Missing person fixture';
select pg_temp.assert_true((select count(*)=4 from my_observations()),'owner sees held reports');
select pg_temp.assert_true((select count(*)=3 from my_observations() where status='review' and privacy_class='restricted' and place_name='Regional information' and latitude=61 and longitude=-150),'sensitive events held and location generalized by server');
select pg_temp.denied($q$select set_observation_assessment(current_setting('test.road')::uuid,'urgent','active','Client forgery','Test evidence','Forged',now()+interval '1 hour')$q$,'ordinary reporter cannot grade');
select pg_temp.denied($q$insert into observation_assessments(observation_id,level,lifecycle,reason) values(current_setting('test.road')::uuid,'urgent','active','Client forgery')$q$,'direct grade write blocked');
select pg_temp.denied($q$insert into moderators values(auth.uid())$q$,'self provision moderator blocked');
update observation_catalog_types set definition='{}';
select pg_temp.assert_true((select bool_and(definition<>'{}'::jsonb) from observation_catalog_types),'catalog tampering cannot change rows');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from my_observations()),'other reporter cannot read held reports through owner RPC');
select pg_temp.assert_true((select count(*)=1 from observation_feed),'other reporter only sees public reports');
reset role;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true((select count(*)=1 from observation_feed),'anonymous feed excludes private reports');
select pg_temp.assert_true((select count(*)=0 from observation_assessments),'assessment actor and evidence private');
select pg_temp.assert_true((select count(*)=0 from observation_publication_reviews),'privacy audit private');
select pg_temp.denied($q$select author_id from observation_feed$q$,'public view excludes author identity');
select pg_temp.assert_true((select assessment_state='not_assessed' from get_public_assessment(current_setting('test.shooting')::uuid)),'assessment lookup does not reveal held report');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select pg_temp.assert_true((select count(*)=4 from staff_review_queue()),'staff queue includes held reports');
select pg_temp.denied($q$select moderate_report(current_setting('test.shooting')::uuid,'approve','Legacy bypass')$q$,'legacy approval cannot bypass privacy workflow');
select pg_temp.denied($q$select review_observation(current_setting('test.shooting')::uuid,'approve','reviewed','Missing privacy check',false,'privacy_review','Documented reference','Safe public title','Safe public description.')$q$,'privacy acknowledgement required');
select pg_temp.denied($q$select review_observation(current_setting('test.missing')::uuid,'approve','reviewed','Checked sensitive content',true,'privacy_review','Documented reference','Safe public title','Safe public description.')$q$,'missing person needs source or consent');
select review_observation(current_setting('test.bear')::uuid,'approve','reviewed','Checked sensitive content',true,'privacy_review','Private documented reference','General regional update','Public text checked for sensitive details.');
select pg_temp.assert_true((select not (answers ? 'other_animal') and place_name='Regional information' from observation_feed where id=current_setting('test.bear')::uuid),'publication strips sensitive free text and keeps regional area');
select pg_temp.assert_true((select before_content->'answers'->>'other_animal'='PRIVATE TEST DETAIL' from observation_publication_reviews limit 1),'private audit preserves original content');
select pg_temp.assert_true((select count(*)=1 from observations_in_bounds(-151,60,-148,62)),'regional publications do not become incident pins');
select pg_temp.denied($q$select set_observation_assessment(current_setting('test.road')::uuid,'urgent','active','Staff test reason','','Public note',now()+interval '1 hour')$q$,'urgent needs supporting evidence');
select pg_temp.denied($q$select set_observation_assessment(current_setting('test.road')::uuid,'urgent','active','Staff test reason','Private evidence','Public note',now()+interval '7 hours')$q$,'urgent review within six hours');
select pg_temp.denied($q$select set_observation_assessment(current_setting('test.road')::uuid,'caution','active','Staff test reason','','Public note',now()+interval '25 hours')$q$,'all active assessments expire within 24 hours');
select set_observation_assessment(current_setting('test.road')::uuid,'urgent','active','Staff test reason','PRIVATE EVIDENCE','Public note',now()+interval '1 hour');
select pg_temp.assert_true((select assessment_level='urgent' and assessment_note='Public note' from get_public_assessment(current_setting('test.road')::uuid)),'active grade public summary');
select pg_temp.assert_true((select verification='unverified' from observation_feed where id=current_setting('test.road')::uuid),'risk assignment does not verify observation');
select set_observation_assessment(current_setting('test.road')::uuid,'caution','active','Downgrade after review','Updated reference','Caution note',now()+interval '1 hour');
select pg_temp.assert_true((select assessment_level='caution' from get_public_assessment(current_setting('test.road')::uuid)),'latest downgrade replaces urgent grade');
select set_observation_assessment(current_setting('test.road')::uuid,'caution','resolved','Resolved after review','','',null);
select pg_temp.assert_true((select assessment_level='none' and assessment_state='resolved' from get_public_assessment(current_setting('test.road')::uuid)),'resolved grade removes active risk');
select set_observation_assessment(current_setting('test.road')::uuid,'caution','disputed','Disputed after review','','',null);
select pg_temp.assert_true((select assessment_level='none' and assessment_state='disputed' from get_public_assessment(current_setting('test.road')::uuid)),'disputed grade removes active risk');
update observation_assessments set reason='Tamper audit';
select pg_temp.assert_true((select count(*)=0 from observation_assessments where reason='Tamper audit'),'staff cannot rewrite assessment history');
reset role;
insert into observation_assessments(observation_id,level,lifecycle,reason,public_note,expires_at) values(current_setting('test.road')::uuid,'urgent','active','Expired fixture record','Old public warning',now()-interval '1 second');
set local role anon;
select pg_temp.assert_true((select assessment_level='none' and assessment_state='expired' and assessment_note is null from get_public_assessment(current_setting('test.road')::uuid)),'server removes expired grade and warning without background job');
select pg_temp.assert_true((select count(*)=0 from observation_assessments),'all assessment history remains private');
rollback;
